import { describe, expect, test } from "bun:test";
import { resolve } from "node:path";
import {
  defaultRepo,
  inspectSubmodules,
  parseForksManifest,
  parseGitmodules,
  parseWorktreePorcelain,
} from "./vcs.ts";

const root = resolve(import.meta.dir, "..");

describe("vcs parsers & repo identity", () => {
  test("defaultRepo resolves to aphrody-labs/aphrody", () => {
    expect(defaultRepo(root)).toBe("aphrody-labs/aphrody");
  });

  test("parseGitmodules parses .gitmodules cleanly", () => {
    const sample = `
# Generated by ay manifests
[submodule "apps/rosegriffon"]
\tpath = apps/rosegriffon
\turl = https://github.com/aphrody-labs/rosegriffon.git
\tbranch = main
[submodule "apps/shenron"]
\tpath = apps/shenron
\turl = https://github.com/aphrody-labs/shenron.git
\tbranch = main
`;
    expect(parseGitmodules(sample)).toEqual([
      {
        name: "apps/rosegriffon",
        path: "apps/rosegriffon",
        url: "https://github.com/aphrody-labs/rosegriffon.git",
        branch: "main",
      },
      {
        name: "apps/shenron",
        path: "apps/shenron",
        url: "https://github.com/aphrody-labs/shenron.git",
        branch: "main",
      },
    ]);
  });

  test("parseWorktreePorcelain parses main, detached, and prunable entries", () => {
    const raw = [
      "worktree /repo",
      "HEAD 0123456789abcdef0123456789abcdef01234567",
      "branch refs/heads/main",
      "",
      "worktree /repo/.worktrees/wasm-bench",
      "HEAD fedcba9876543210fedcba9876543210fedcba98",
      "detached",
      "prunable gitdir file points to non-existent location",
    ].join("\n");
    const parsed = parseWorktreePorcelain(raw);
    expect(parsed).toHaveLength(2);
    expect(parsed[0]).toEqual({
      path: "/repo",
      head: "0123456789abcdef0123456789abcdef01234567",
      branch: "main",
      bare: false,
      prunable: null,
      locked: null,
    });
    expect(parsed[1]?.branch).toBeNull();
    expect(parsed[1]?.prunable).toContain("non-existent");
  });

  test("parseForksManifest extracts upstream owner/repo and language", () => {
    const raw = `# comment\nWebAssembly/binaryen C++\nemscripten-core/emscripten Python\naphrody-labs/llvm-project\n`;
    expect(parseForksManifest(raw)).toEqual([
      {
        upstream: "WebAssembly/binaryen",
        repoName: "binaryen",
        language: "C++",
      },
      {
        upstream: "emscripten-core/emscripten",
        repoName: "emscripten",
        language: "Python",
      },
      {
        upstream: "aphrody-labs/llvm-project",
        repoName: "llvm-project",
        language: "",
      },
    ]);
  });

  test("inspectSubmodules reads live monorepo gitlinks and src.lock.json", () => {
    const subs = inspectSubmodules(root);
    expect(subs.map((s) => s.path)).toEqual([
      "apps/rosegriffon",
      "apps/shenron",
    ]);
    for (const s of subs) {
      expect(s.gitlinkSha).toMatch(/^[0-9a-f]{40}$/);
      expect(s.lockSha).toMatch(/^[0-9a-f]{40}$/);
    }
  });
});
